    userid: string,
    name: string,
    sex: Sex,
    password: string,
    email: string,
    faculty: string,
    loanednumber: number,
    borrowstatus: BorrowStatus,
    suspensiondays: number,
    overduefee: number,
  ): boolean {
    /*Definition Start*/
    let newUser: User = l({
      logic: () =>
        getRepository(User).find(
          (o: any) =>
            l({
              logic: () => o.UserID === userid,
              description: "o.UserID=userid",
            }).build().pass,
        ),
      description: "User.allInstance()->any(o|o.UserID=userid)",
    }).build().pass;
    let isExistingUser: boolean = l({
      logic: () => getRepository(User).includes(newUser),
      description: "User.allInstance()->includes(newUser)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(userid),
        description: "userid.oclIsUndefined()",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(name),
          description: "name.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(sex),
          description: "sex.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(password),
          description: "password.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(email),
          description: "email.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(faculty),
          description: "faculty.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(loanednumber),
          description: "loanednumber.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(borrowstatus),
          description: "borrowstatus.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(suspensiondays),
          description: "suspensiondays.oclIsUndefined()",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(overduefee),
          description: "overduefee.oclIsUndefined()",
        })
        .and({
          logic: () => isExistingUser === false,
          description: "isExistingUser=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (newUser = new User()),
      description: "newUser.oclIsNew()",
    })
      .and({
        execute: () => getRepository(User).push(newUser),
        description: "User.allInstance()->includes(newUser)",
      })
      .and({
        execute: () => (newUser.UserID = userid),
        description: "newUser.UserID=userid",
      })
      .and({
        execute: () => (newUser.Name = name),
        description: "newUser.Name=name",
      })
      .and({
        execute: () => (newUser.Sex = sex),
        description: "newUser.Sex=sex",
      })
      .and({
        execute: () => (newUser.Password = password),
        description: "newUser.Password=password",
      })
      .and({
        execute: () => (newUser.Email = email),
        description: "newUser.Email=email",
      })
      .and({
        execute: () => (newUser.Faculty = faculty),
        description: "newUser.Faculty=faculty",
      })
      .and({
        execute: () => (newUser.LoanedNumber = loanednumber),
        description: "newUser.LoanedNumber=loanednumber",
      })
      .and({
        execute: () => (newUser.BorrowStatus = borrowstatus),
        description: "newUser.BorrowStatus=borrowstatus",
      })
      .and({
        execute: () => (newUser.SuspensionDays = suspensiondays),
        description: "newUser.SuspensionDays=suspensiondays",
      })
      .and({
        execute: () => (newUser.OverDueFee = overduefee),
        description: "newUser.OverDueFee=overduefee",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ManageUserCRUDService_AutoGenerated };

